// @name Solitaire
// @background #2f5a48
// @refresh 3600
// Klondike solitaire for a touch screen. Tap a card to pick it up (with the
// cards on it), then tap where it goes; tap it twice to send it home (its
// foundation, else a column that takes it). Tap the stock to draw. Undo goes
// back as far as you like. The game in progress is kept on the frame.
import { deal, move, autoTarget, drawStock, won, canFinish, finish, cardsAt } from './logic'
import { Face, Back, Place } from './cards'
import { highContrast, canvasOf, Button, OptionsPage } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#2f5a48] text-white',
    muted: 'text-[#cfe0d6]',
    button: 'bg-[#244a3a] text-white active:bg-[#1c3b2e]',
    primary: 'bg-[#e8b33a] text-[#1f2933] active:bg-[#f0c45a]',
    on: 'bg-[#e8b33a] text-[#1f2933]',
    off: 'bg-[#244a3a] text-white',
    banner: 'bg-[#fffdf8] text-[#1f2933]',
    card: '#fffdf8',
    cardEdge: '#b9b2a2',
    red: '#b8432f',
    black: '#1f2933',
    hollowRed: false,
    lit: '#e8b33a',
    back: '#1f3a5f',
    backEdge: '#16294a',
    backLine: '#5b7aa6',
    slot: '#2a5141',
    slotEdge: '#4d7a66',
    slotMark: '#6e9a85',
    faint: { red: '#3f6b58', black: '#3f6b58', hollowRed: false },
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    banner: 'bg-white text-black border-4 border-black',
    card: '#ffffff',
    cardEdge: '#000000',
    red: '#000000',
    black: '#000000',
    hollowRed: true,
    lit: '#000000',
    back: '#000000',
    backEdge: '#000000',
    backLine: '#ffffff',
    slot: '#ffffff',
    slotEdge: '#000000',
    slotMark: '#000000',
    faint: { red: '#000000', black: '#000000', hollowRed: true },
  },
}

const drawOf = (app) => (String(app.state.draw) === '3' ? 3 : 1)

// The game in progress, kept in the scene's private `game` field, with the
// positions before each move (as text) for undo.
const loadGame = (app) => {
  const g = app.state.game
  return g && Array.isArray(g.tab) && g.tab.length === 7 && Array.isArray(g.found) ? g : null
}
const save = (game) => frameos.setState('game', game)
const snapshot = (game) => JSON.stringify({ ...game, undo: undefined })

// Runs `change` on the game; when it changes something, the position before
// goes on the undo list (the last 40) and the game is saved.
const play = (app, change: (game) => boolean) => {
  const game = loadGame(app)
  if (!game) return false
  const before = snapshot(game)
  if (!change(game)) return false
  game.undo = [...(game.undo || []).slice(-39), before]
  save(game)
  return true
}

const undo = (app) => {
  const game = loadGame(app)
  if (!game || !game.undo || !game.undo.length) return
  const undoList = game.undo.slice(0, -1)
  const previous = JSON.parse(game.undo[game.undo.length - 1])
  save({ ...previous, undo: undoList })
  frameos.remember('sel', null)
}

const restart = (app) => {
  save(deal(drawOf(app), Math.random))
  frameos.remember('sel', null)
  frameos.remember('page', null)
}

const same = (a, b) => a && b && a.pile === b.pile && a.col === b.col && a.index === b.index

// A tap on a card or a place. `from` is the card tapped (null for an empty
// place or the space under a column), `to` where a held card would go.
const tap = (app, from, to) => {
  const game = loadGame(app)
  if (!game || won(game)) return
  const sel = frameos.recall('sel')
  if (sel) {
    // The same card again: send it home.
    if (same(sel, from)) {
      const target = autoTarget(game, sel)
      if (target) play(app, (g) => move(g, sel, target))
      frameos.remember('sel', null)
      return
    }
    if (to && play(app, (g) => move(g, sel, to))) {
      frameos.remember('sel', null)
      return
    }
  }
  frameos.remember('sel', from && cardsAt(game, from).length ? from : null)
}

const tapStock = (app) => {
  frameos.remember('sel', null)
  play(app, drawStock)
}

// Frames with buttons: forward draws from the stock, back is undo. On a
// keyboard: space draws, U undoes, N deals again.
export function onEvent(app, context) {
  const event = context.event
  if (event === 'forward') tapStock(app)
  else if (event === 'back') undo(app)
  else if (event === 'keyDown') {
    const p = context.payload || {}
    if (p.ctrl || p.alt || p.meta) return false
    const key = String(p.key || '').toLowerCase()
    if (key === ' ') tapStock(app)
    else if (key === 'u' || key === 'backspace') undo(app)
    else if (key === 'n') restart(app)
    else return false
  } else return false
  return true
}

// Where each card of a column sits, from the top of the column: face-down
// cards closer together than face-up ones, and all of them closer when the
// column would run off the bottom.
const columnOffsets = (count: number, down: number, cardH: number, height: number) => {
  const downStep = cardH * 0.13
  const upStep = cardH * 0.3
  const up = count - down
  const need = down * downStep + Math.max(0, up - 1) * upStep
  const scale = need > 0 ? Math.min(1, (height - cardH) / need) : 1
  const ys: number[] = []
  let y = 0
  for (let i = 0; i < count; i++) {
    ys.push(y)
    y += (i < down ? downStep : upStep) * scale
  }
  return ys
}

// The seven columns as one drawing, `cardW` cards with `gap` between, and the
// tap that finds the card under the finger.
const Tableau = ({ app, t, game, sel, cardW, cardH, gap, height }) => {
  const width = cardW * 7 + gap * 6
  const parts = []
  const offsets = game.tab.map((column, col) => columnOffsets(column.length, game.down[col], cardH, height))
  for (let col = 0; col < 7; col++) {
    const column = game.tab[col]
    const x = col * (cardW + gap)
    if (!column.length) {
      parts.push(<Place t={t} x={x} y={0} w={cardW} h={cardH} />)
      continue
    }
    const lit = sel && sel.pile === 'tab' && sel.col === col ? sel.index : 99
    for (let i = 0; i < column.length; i++) {
      const y = offsets[col][i]
      if (i < game.down[col]) parts.push(<Back t={t} x={x} y={y} w={cardW} h={cardH} />)
      else parts.push(<Face t={t} card={column[i]} x={x} y={y} w={cardW} h={cardH} full={i === column.length - 1} lit={i >= lit} />)
    }
  }
  return (
    <div className={`w-[${width}px] h-[${height}px] shrink-0`}
      onClick={(e) => {
        const col = Math.floor((e.localX / e.width) * width / (cardW + gap))
        if (col < 0 || col > 6) return
        const column = game.tab[col]
        const y = (e.localY / e.height) * height
        let index = -1
        for (let i = column.length - 1; i >= 0; i--) {
          if (y >= offsets[col][i]) {
            index = i === column.length - 1 && y > offsets[col][i] + cardH ? -1 : i
            break
          }
        }
        const from = index >= game.down[col] ? { pile: 'tab', col, index } : null
        tap(app, from, { pile: 'tab', col })
      }}>
      <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>{parts}</svg>
    </div>
  )
}

// The foundations, `vertical` in a column or in a row, the top card of each.
const Foundations = ({ app, t, game, sel, cardW, cardH, gap, vertical }) => {
  const width = vertical ? cardW : cardW * 4 + gap * 3
  const height = vertical ? cardH * 4 + gap * 3 : cardH
  const parts = []
  for (let k = 0; k < 4; k++) {
    const x = vertical ? 0 : k * (cardW + gap)
    const y = vertical ? k * (cardH + gap) : 0
    const pile = game.found[k]
    const lit = sel && sel.pile === 'found' && sel.col === k
    if (pile.length) parts.push(<Face t={t} card={pile[pile.length - 1]} x={x} y={y} w={cardW} h={cardH} full={true} lit={lit} />)
    else parts.push(<Place t={t} x={x} y={y} w={cardW} h={cardH} suit={k} />)
  }
  return (
    <div className={`w-[${width}px] h-[${height}px] shrink-0`}
      onClick={(e) => {
        const along = vertical ? (e.localY / e.height) * height : (e.localX / e.width) * width
        const k = Math.min(3, Math.floor(along / ((vertical ? cardH : cardW) + gap)))
        tap(app, game.found[k].length ? { pile: 'found', col: k } : null, { pile: 'found', col: k })
      }}>
      <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>{parts}</svg>
    </div>
  )
}

// The stock and the waste (its top three fanned when drawing three), one
// under the other or side by side.
const StockWaste = ({ app, t, game, sel, cardW, cardH, gap, vertical }) => {
  const fan = game.draw === 3 ? (vertical ? cardH * 0.2 : cardW * 0.25) : 0
  const width = vertical ? cardW : cardW * 2 + gap + fan * 2
  const height = vertical ? cardH * 2 + gap + fan * 2 : cardH
  const parts = []
  if (game.stock.length) parts.push(<Back t={t} x={0} y={0} w={cardW} h={cardH} />)
  else parts.push(<Place t={t} x={0} y={0} w={cardW} h={cardH} mark={game.waste.length ? 'again' : ''} />)
  const wx = vertical ? 0 : cardW + gap
  const wy = vertical ? cardH + gap : 0
  const shown = game.waste.slice(-Math.max(1, game.draw))
  if (!shown.length) parts.push(<Place t={t} x={wx} y={wy} w={cardW} h={cardH} />)
  shown.forEach((card, i) => {
    const last = i === shown.length - 1
    parts.push(
      <Face t={t} card={card} x={wx + (vertical ? 0 : fan * i)} y={wy + (vertical ? fan * i : 0)} w={cardW} h={cardH}
        full={last} lit={last && sel && sel.pile === 'waste'} />,
    )
  })
  return (
    <div className={`w-[${width}px] h-[${height}px] shrink-0`}
      onClick={(e) => {
        const along = vertical ? (e.localY / e.height) * height : (e.localX / e.width) * width
        if (along < (vertical ? cardH : cardW)) tapStock(app)
        else if (along > (vertical ? cardH : cardW) + gap) tap(app, { pile: 'waste' }, null)
      }}>
      <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>{parts}</svg>
    </div>
  )
}

export function get(app, context) {
  const ui = canvasOf(app, context)
  const t = highContrast(app) ? THEMES.high : THEMES.color

  if (frameos.recall('page') === 'options') {
    const rows = [{ field: 'draw', label: 'Draw from the stock', value: String(drawOf(app)), options: [['1', 'One card'], ['3', 'Three cards']] }]
    return <OptionsPage ui={ui} t={t} title="Solitaire" rows={rows}
      onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
  }

  let game = loadGame(app)
  if (!game) {
    game = deal(drawOf(app), Math.random)
    save(game)
  } else if (game.draw !== drawOf(app)) {
    // One or three from the stock may change in the middle of a game.
    game = { ...game, draw: drawOf(app) }
    save(game)
  }
  const sel = frameos.recall('sel')
  const gap = Math.max(4, Math.round(Math.min(ui.W, ui.H) * 0.014))
  const done = won(game)
  const finishable = canFinish(game)
  const status = `${game.moves} ${game.moves === 1 ? "move" : "moves"}`
  const finishButton = finishable
    ? <Button ui={ui} grow className={t.primary} onClick={() => play(app, (g) => { finish(g); return true })}>Finish</Button>
    : null
  const banner = done ? (
    <div className={`absolute inset-x-[15%] top-[30%] rounded-2xl p-[${ui.pad}px] flex flex-col items-center gap-[${ui.gap}px] ${t.banner}`}>
      <span className={`text-[${ui.title}px] font-bold`}>You won!</span>
      <span className={`text-[${ui.text}px]`}>{`In ${game.moves} moves`}</span>
      <Button ui={ui} className={`w-full ${t.primary}`} onClick={() => restart(app)}>Deal again</Button>
    </div>
  ) : null

  // Wide screens: stock and waste on the left, the columns, the foundations
  // on the right, all at full height. Tall and square ones: the classic
  // table, stock and foundations along the top.
  if (ui.W >= ui.H * 1.3) {
    const cardW = Math.floor(Math.min((ui.W - ui.pad * 2 - gap * 8) / 9, (ui.H - ui.pad * 2 - gap * 3) / 4 / 1.4))
    const cardH = Math.round(cardW * 1.4)
    const buttonH = Math.max(44, Math.round(cardW * 0.55))
    const small = `h-[${buttonH}px] w-full rounded-lg flex items-center justify-center text-[${Math.round(Math.min(ui.small, cardW / 4.6))}px] font-semibold`
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${gap}px] justify-center ${t.page}`}>
        <div className={`w-[${cardW}px] h-full flex flex-col gap-[${gap}px]`}>
          <StockWaste app={app} t={t} game={game} sel={sel} cardW={cardW} cardH={cardH} gap={gap} vertical={true} />
          <div className="flex-1" />
          <span className={`text-[${Math.round(Math.min(ui.small, cardW / 4.2))}px] text-center ${t.muted}`}>{status}</span>
          {finishable ? <div className={`${small} ${t.primary}`} onClick={() => play(app, (g) => { finish(g); return true })}>Finish</div> : null}
          <div className={`${small} ${t.button}`} onClick={() => undo(app)}>Undo</div>
          <div className={`${small} ${done ? t.primary : t.button}`} onClick={() => restart(app)}>New</div>
          <div className={`${small} ${t.button}`} onClick={() => frameos.remember('page', 'options')}>Options</div>
        </div>
        <Tableau app={app} t={t} game={game} sel={sel} cardW={cardW} cardH={cardH} gap={gap} height={ui.H - ui.pad * 2} />
        <Foundations app={app} t={t} game={game} sel={sel} cardW={cardW} cardH={cardH} gap={gap} vertical={true} />
        {banner}
      </div>
    )
  }
  const buttonsH = ui.button
  const cardW = Math.floor(Math.min((ui.W - ui.pad * 2 - gap * 6) / 7, ((ui.H - ui.pad * 2 - buttonsH - gap * 2) * 0.3) / 1.4))
  const cardH = Math.round(cardW * 1.4)
  const tableW = cardW * 7 + gap * 6
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${gap}px] items-center ${t.page}`}>
      <div className={`flex justify-between w-[${tableW}px]`}>
        <StockWaste app={app} t={t} game={game} sel={sel} cardW={cardW} cardH={cardH} gap={gap} vertical={false} />
        <Foundations app={app} t={t} game={game} sel={sel} cardW={cardW} cardH={cardH} gap={gap} vertical={false} />
      </div>
      <Tableau app={app} t={t} game={game} sel={sel} cardW={cardW} cardH={cardH} gap={gap}
        height={ui.H - ui.pad * 2 - cardH - buttonsH - gap * 2} />
      <div className={`flex items-center w-[${tableW}px] gap-[${gap}px]`}>
        <span className={`flex-1 text-[${ui.small}px] ${t.muted}`}>{status}</span>
        {finishButton}
        <Button ui={ui} className={t.button} onClick={() => undo(app)}>Undo</Button>
        <Button ui={ui} className={done ? t.primary : t.button} onClick={() => restart(app)}>New</Button>
        <Button ui={ui} className={t.button} onClick={() => frameos.remember('page', 'options')}>Options</Button>
      </div>
      {banner}
    </div>
  )
}

