// Klondike's rules. Pure: no frameos calls, so it can be checked with plain
// node.
//
// A card is a number 0..51: suit = Math.floor(card / 13) (0 spades, 1 hearts,
// 2 diamonds, 3 clubs), rank = card % 13 (0 ace .. 12 king). A game:
//   stock, waste   cards, the top last
//   found          four piles, one per suit, the top last
//   tab            seven columns, the top last; the first down[i] of column i
//                  are face down
//   draw           1 or 3 cards from the stock at a time
//   moves          moves made

export type Game = {
  stock: number[]
  waste: number[]
  found: number[][]
  tab: number[][]
  down: number[]
  draw: number
  moves: number
}

export const suitOf = (card: number) => Math.floor(card / 13)
export const rankOf = (card: number) => card % 13
export const isRed = (card: number) => suitOf(card) === 1 || suitOf(card) === 2

export function deal(draw: number, random: () => number): Game {
  const deck: number[] = []
  for (let i = 0; i < 52; i++) deck.push(i)
  for (let i = 51; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    const swap = deck[i]
    deck[i] = deck[j]
    deck[j] = swap
  }
  const tab: number[][] = []
  const down: number[] = []
  for (let col = 0; col < 7; col++) {
    tab.push(deck.splice(0, col + 1))
    down.push(col)
  }
  return { stock: deck, waste: [], found: [[], [], [], []], tab, down, draw, moves: 0 }
}

// Where a selection comes from: the waste's top, a foundation's top, or a
// tableau column from card `index` down.
export type From = { pile: 'waste' } | { pile: 'found'; col: number } | { pile: 'tab'; col: number; index: number }
// Where it may go: a foundation or a column.
export type To = { pile: 'found'; col: number } | { pile: 'tab'; col: number }

export function cardsAt(game: Game, from: From): number[] {
  if (from.pile === 'waste') return game.waste.length ? [game.waste[game.waste.length - 1]] : []
  if (from.pile === 'found') {
    const pile = game.found[from.col]
    return pile.length ? [pile[pile.length - 1]] : []
  }
  if (from.index < game.down[from.col]) return []
  return game.tab[from.col].slice(from.index)
}

export function canPlace(game: Game, cards: number[], to: To) {
  if (!cards.length) return false
  const first = cards[0]
  if (to.pile === 'found') {
    if (cards.length !== 1) return false
    const pile = game.found[to.col]
    if (suitOf(first) !== to.col) return false
    return pile.length ? rankOf(pile[pile.length - 1]) === rankOf(first) - 1 : rankOf(first) === 0
  }
  const column = game.tab[to.col]
  if (!column.length) return rankOf(first) === 12
  const top = column[column.length - 1]
  return isRed(top) !== isRed(first) && rankOf(top) === rankOf(first) + 1
}

// Moves the cards at `from` to `to` when the rules allow it; turns over the
// card it uncovers. Answers whether it moved.
export function move(game: Game, from: From, to: To) {
  const cards = cardsAt(game, from)
  if (!canPlace(game, cards, to)) return false
  if (from.pile === to.pile && from.col === to.col) return false
  if (from.pile === 'waste') game.waste.pop()
  else if (from.pile === 'found') game.found[from.col].pop()
  else {
    game.tab[from.col].splice(from.index)
    if (game.down[from.col] >= game.tab[from.col].length) game.down[from.col] = Math.max(0, game.tab[from.col].length - 1)
  }
  if (to.pile === 'found') game.found[to.col].push(...cards)
  else game.tab[to.col].push(...cards)
  game.moves++
  return true
}

// The best place for a card a player tapped twice: its foundation, else a
// column that takes it (one with cards before an empty one).
export function autoTarget(game: Game, from: From): To | null {
  const cards = cardsAt(game, from)
  if (!cards.length) return null
  if (cards.length === 1 && from.pile !== 'found') {
    const to: To = { pile: 'found', col: suitOf(cards[0]) }
    if (canPlace(game, cards, to)) return to
  }
  let empty: To | null = null
  for (let col = 0; col < 7; col++) {
    if (from.pile === 'tab' && from.col === col) continue
    const to: To = { pile: 'tab', col }
    if (!canPlace(game, cards, to)) continue
    if (game.tab[col].length) return to
    // A king already at the bottom of its column has nowhere better to go.
    if (!empty && !(from.pile === 'tab' && from.index === 0)) empty = to
  }
  return empty
}

// The stock: draw one or three onto the waste; an empty stock takes the
// waste back, turned over.
export function drawStock(game: Game) {
  if (game.stock.length) {
    for (let i = 0; i < game.draw && game.stock.length; i++) game.waste.push(game.stock.pop() as number)
  } else if (game.waste.length) {
    game.stock = game.waste.reverse()
    game.waste = []
  } else return false
  game.moves++
  return true
}

export const won = (game: Game) => game.found.every((pile) => pile.length === 13)

// Every card turned up and the stock and waste empty: the rest is only
// moves to the foundations, which `finish` makes.
export const canFinish = (game: Game) =>
  !won(game) && !game.stock.length && !game.waste.length && game.down.every((d) => d === 0)

export function finish(game: Game) {
  for (let guard = 0; guard < 60 && !won(game); guard++) {
    let moved = false
    for (let col = 0; col < 7 && !moved; col++) {
      const column = game.tab[col]
      if (!column.length) continue
      const card = column[column.length - 1]
      moved = move(game, { pile: 'tab', col, index: column.length - 1 }, { pile: 'found', col: suitOf(card) })
    }
    if (!moved) break
  }
}

